void ConfigScreen::list_1(void)
{
  Serial.println("ConfigScreen: list_1");
  tft->fillScreen(0x0);
  tft->createSprite(240, 240);
  tft->fillSprite(TFT_BLACK);
  // rect 3
  tft->fillRoundRect(5, 103, 230, 35, 15, 0XFFFF);
  // string 2
  tft->setTextColor(0x4208);
  tft->setTextSize(1);
  tft->setFreeFont(&FreeSansBold9pt7b);
  tft->drawString("Connection status", 42, 113);
  // string 3
  tft->setTextColor(0xFFFF);
  tft->setFreeFont(&FreeSans9pt7b);
  tft->drawString("Disconnect device", 47, 160);
  // image-link
  tft->pushImage(208, 110, 20, 20, image_image_link_pixels);
  tft->pushSprite(0, 0);
}